CREATE TYPE public.synthesis_domain AS ENUM ('Quantum Computing', 'Distributed Consensus', 'Biomedical Reasoning', 'Obfuscated Code Logic');
CREATE TYPE public.quantization_level AS ENUM ('FP16', 'BF16', 'INT8', 'INT4', 'AWQ', 'GGUF_Q4');
CREATE TYPE public.redteam_vector AS ENUM ('Prompt Injection', 'System Prompt Leak', 'Jailbreak Bypass', 'Hallucinated Package Exploitation');
CREATE TABLE public.synthetic_benchmark_suites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, generator_model_id text, target_domain public.synthesis_domain NOT NULL, contamination_risk_score numeric, difficulty_rating numeric NOT NULL DEFAULT 5, created_by uuid NOT NULL DEFAULT auth.uid(), source text NOT NULL DEFAULT 'local-template', report jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT suite_risk_range CHECK (contamination_risk_score BETWEEN 0 AND 1), CONSTRAINT suite_difficulty_range CHECK (difficulty_rating BETWEEN 1 AND 10));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.synthetic_benchmark_suites TO authenticated;
GRANT ALL ON public.synthetic_benchmark_suites TO service_role;
ALTER TABLE public.synthetic_benchmark_suites ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own suites" ON public.synthetic_benchmark_suites FOR ALL TO authenticated USING (created_by = auth.uid()) WITH CHECK (created_by = auth.uid());
CREATE TABLE public.hardware_telemetry_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), model_id text NOT NULL, host_provider text NOT NULL, quantization_level public.quantization_level NOT NULL, memory_bandwidth_gbps numeric NOT NULL, energy_efficiency_tok_per_joule numeric NOT NULL, inter_gpu_interconnect_latency_us numeric, kv_cache_hit_ratio numeric, created_by uuid NOT NULL DEFAULT auth.uid(), source text NOT NULL DEFAULT 'imported', report jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT hardware_nonnegative CHECK (memory_bandwidth_gbps >= 0 AND energy_efficiency_tok_per_joule >= 0 AND inter_gpu_interconnect_latency_us >= 0), CONSTRAINT cache_ratio CHECK (kv_cache_hit_ratio BETWEEN 0 AND 1));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.hardware_telemetry_profiles TO authenticated;
GRANT ALL ON public.hardware_telemetry_profiles TO service_role;
ALTER TABLE public.hardware_telemetry_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own profiles" ON public.hardware_telemetry_profiles FOR ALL TO authenticated USING (created_by = auth.uid()) WITH CHECK (created_by = auth.uid());
CREATE TABLE public.security_redteam_scans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), model_id text NOT NULL, attack_vector public.redteam_vector NOT NULL, success_rate_pct numeric NOT NULL, safety_guardrail_latency_overhead_ms integer NOT NULL, attack_payload_samples jsonb NOT NULL DEFAULT '[]'::jsonb, created_by uuid NOT NULL DEFAULT auth.uid(), source text NOT NULL DEFAULT 'sample-replay', report jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT redteam_success_range CHECK (success_rate_pct BETWEEN 0 AND 100), CONSTRAINT guardrail_overhead CHECK (safety_guardrail_latency_overhead_ms >= 0));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.security_redteam_scans TO authenticated;
GRANT ALL ON public.security_redteam_scans TO service_role;
ALTER TABLE public.security_redteam_scans ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own scans" ON public.security_redteam_scans FOR ALL TO authenticated USING (created_by = auth.uid()) WITH CHECK (created_by = auth.uid());
CREATE INDEX suites_owner_date ON public.synthetic_benchmark_suites (created_by, created_at DESC);
CREATE INDEX hardware_owner_date ON public.hardware_telemetry_profiles (created_by, created_at DESC);
CREATE INDEX scans_owner_date ON public.security_redteam_scans (created_by, created_at DESC);